-- generated by themer ({{theme}}, {{mode}}, #{{bg}} #{{fg}} #{{acc}}): the color scheme
-- "themer" and the font; WezTerm reloads when these lines change
config.color_scheme_dirs = config.color_scheme_dirs or {}
table.insert(config.color_scheme_dirs, "{{scheme_dir}}")
config.color_scheme = "themer"
config.font = require('wezterm').font("{{font_family}}")
config.font_size = {{font_size}}
config.window_frame = config.window_frame or {}
config.window_frame.active_titlebar_bg = "#{{bg}}"
config.window_frame.inactive_titlebar_bg = "#{{bg}}"
config.window_frame.active_titlebar_fg = "#{{fg}}"
config.window_frame.inactive_titlebar_fg = "#{{fg}}"
config.window_frame.button_bg = "#{{bg}}"
config.window_frame.button_fg = "#{{fg}}"
config.window_frame.button_hover_bg = "#{{control_hover}}"
config.window_frame.button_hover_fg = "#{{fg}}"
